// 6/28 1281「有塵、水壓不足」修正日期至 7/2 並補備註（同日另一筆蟲咬記錄不動）
const SPECIAL_1281 = { match: { date: '2026-06-28', room: '1281', comment: '有塵、水壓不足' }, patch: { date: '2026-07-02', actual_cause: '備註：客人自帶的毛巾發臭' } }

const existing = await req('GET', 'complaints?select=id,date,room,guest_comment')
const seen = new Set(existing.map(c => `${c.date}|${String(c.room).trim()}|${c.guest_comment}`))

let ins = 0, skip = 0
for (const [date, source, room, category, dept, nature, guest_comment, improvement, actual_cause] of ROWS) {
  if (seen.has(`${date}|${room}|${guest_comment}`)) { skip++; continue }
  await req('POST', 'complaints', {
    date, source, room, category, dept, nature, guest_comment,
    actual_cause: actual_cause || '', correct_standard: '', improvement: improvement || '',
    shared: false, check_scheduled: false, recurred: false, photos: [],
  })
  ins++
}
console.log(`插入 ${ins} 筆，略過已存在 ${skip} 筆`)

let upd = 0
for (const [date, room, patch] of UPDATES) {
  const rows = await req('PATCH', `complaints?date=eq.${date}&room=eq.${encodeURIComponent(room)}`, patch)
  if (rows.length) upd++
}
const sp = existing.find(c => c.date === SPECIAL_1281.match.date && String(c.room).trim() === SPECIAL_1281.match.room && c.guest_comment === SPECIAL_1281.match.comment)
if (sp) { await req('PATCH', `complaints?id=eq.${sp.id}`, SPECIAL_1281.patch); upd++ }
console.log(`修正既有記錄 ${upd}/${UPDATES.length + 1}`)
console.log('完成')
